import{_ as a,o as n,c as t,ae as o}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"OpenAPI and AsyncAPI documents live in openapi/ and asyncapi/","description":"","frontmatter":{"id":"1427717799","title":"OpenAPI and AsyncAPI documents live in openapi/ and asyncapi/","state":"Draft","created":"2026-11-01T00:00:00.000Z","tags":["directory","openapi","asyncapi","documentation"],"category":"Platform"},"headers":[],"relativePath":"adrs/1427717799/README.md","filePath":"adrs/1427717799/README.md"}'),s={name:"adrs/1427717799/README.md"};function i(r,e,c,p,d,l){return n(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="openapi-and-asyncapi-documents-live-in-openapi-and-asyncapi" tabindex="-1">OpenAPI and AsyncAPI documents live in openapi/ and asyncapi/ <a class="header-anchor" href="#openapi-and-asyncapi-documents-live-in-openapi-and-asyncapi" aria-label="Permalink to &quot;OpenAPI and AsyncAPI documents live in openapi/ and asyncapi/&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./../9316364013/README.html">ADR#9316364013</a> reserves <code>proto/</code>, <code>wit/</code> and <code>otel/</code> for schema sources, and <a href="./../4711775939/README.html">ADR#4711775939</a> fixes the layout inside each. OpenAPI and AsyncAPI documents describe HTTP and message-driven interfaces the same way, but neither ADR names a place for them. Repositories place them under <code>docs/</code>, <code>api/</code>, <code>spec/</code> or the repository root, so tooling paths drift and the layout is learned again on every clone.</p><p>Unlike buf or Weaver, neither specification dictates a directory layout, so the second level has to be decided here.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li><p>You <strong>MUST</strong> add <code>openapi/</code> and <code>asyncapi/</code> to the schema source directories reserved by <a href="./../9316364013/README.html">ADR#9316364013</a>, one directory per specification, named after the specification and not after a tool.</p></li><li><p>You <strong>MUST NOT</strong> place these documents in <code>docs/</code>, <code>api/</code> or <code>spec/</code>, or loose at the repository root.</p></li><li><p>You <strong>MUST</strong> keep only hand-written specification documents, and the specification fragments and examples they reference, in the directory. Configuration that drives a tool, such as linting or code generation, goes under <code>.config/&lt;tool&gt;/</code>. Generated code <strong>MUST</strong> live in the language workspace that consumes it.</p></li><li><p>You <strong>MUST NOT</strong> commit a document generated from another schema source, such as <code>proto/</code>, or from code. Generate it at build time instead.</p></li><li><p>You <strong>MUST</strong> write documents in YAML.</p></li><li><p>You <strong>MUST</strong> name the document <code>openapi.yaml</code> or <code>asyncapi.yaml</code>, and place it directly in the directory when the repository describes one interface. When it describes more than one, you <strong>MUST</strong> use <code>&lt;interface&gt;/</code> per interface, where <code>&lt;interface&gt;</code> is unique within the directory and names the component and, when that component exposes several, the audience or version, such as <code>payments-public</code> or <code>payments-admin</code>.</p></li><li><p>You <strong>MAY</strong> place the directory next to a single component or service when the document belongs to that component alone. It <strong>MUST</strong> still use the same name.</p></li><li><p>You <strong>MUST</strong> keep prose about the interface, such as guides and explanations, out of these directories. It follows <a href="./../3223845695/README.html">ADR#3223845695</a>.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── openapi</span></span>
<span class="line"><span>│   ├── openapi.yaml              # one interface</span></span>
<span class="line"><span>│   └── &lt;interface&gt;/openapi.yaml  # more than one interface</span></span>
<span class="line"><span>└── asyncapi</span></span>
<span class="line"><span>    ├── asyncapi.yaml</span></span>
<span class="line"><span>    └── &lt;interface&gt;/asyncapi.yaml</span></span></code></pre></div></li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../9316364013/README.html">ADR#9316364013</a>: Reserved repository directories</li><li><a href="./../4711775939/README.html">ADR#4711775939</a>: Schema source directories</li><li><a href="./../3223845695/README.html">ADR#3223845695</a>: Documentation structure</li><li><a href="https://spec.openapis.org/oas/latest.html#document-structure" target="_blank" rel="noreferrer">OpenAPI Specification, document structure</a></li><li><a href="https://www.asyncapi.com/docs/reference/specification/latest" target="_blank" rel="noreferrer">AsyncAPI specification</a></li></ul>`,8)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
